import type { Duration, FullSchema, Record, TableName } from '../db';
import type { Role } from '../app/Role';
/**
 * Scoring strategy for an assessment or category. Friendly values; the plugin
 * maps them to the backend (`scoring_type`, default `percent`):
 * `percentage`→`percent`, `allOrNothing`→`absolute`.
 */
type ScoringType = 'percentage' | 'allOrNothing';
/**
 * Evaluation method that determines how the assessment behaves. Friendly values;
 * the plugin maps them to the backend (`evaluation_method`, default `assessment`):
 * `assessment`→`assessment`, `survey`→`survey`, `quiz`→`quiz`,
 * `legacyAttestation`→`attestation`, `attestation`→`attestation_v2`,
 * `testPlan`→`testplan`, `riskAssessment`→`risk_assessment`,
 * `vendorRiskAssessment`→`vdr_risk_asmt`.
 */
type EvaluationMethod = 'assessment' | 'survey' | 'quiz' | 'legacyAttestation' | 'attestation' | 'testPlan' | 'riskAssessment' | 'vendorRiskAssessment';
/**
 * Evaluation method used when sourcing questions from a question bank.
 * Superset of {@link EvaluationMethod} with an extra `rating` option.
 *
 * DB: `qb_evaluation_method` (read-only on the platform). `rating`→`rating`.
 */
type QbEvaluationMethod = EvaluationMethod | 'rating';
/**
 * Trigger model for generating assessment instances.
 *
 * DB: `schedule_type`. Default: `'onDemand'`.
 */
type ScheduleType = 'scheduled' | 'onDemand';
/**
 * Recurrence period label, used with `scheduleType: 'scheduled'`.
 *
 * DB: `schedule_period`. Default: `'noLimit'`.
 * - `noLimit` — DB `0`
 * - `onlyOnce` — DB `2`
 * - `weekly` — DB `3`
 * - `monthly` — DB `4`
 * - `yearly` — DB `6`
 * - `daily` — DB `11`
 */
type SchedulePeriod = 'noLimit' | 'onlyOnce' | 'weekly' | 'monthly' | 'yearly' | 'daily';
/**
 * Pagination mode for the Service Portal view.
 *
 * DB: `portal_pagination`. Default: `'category'`.
 */
type PortalPagination = 'category' | 'question' | 'none';
/**
 * Publish lifecycle state.
 *
 * DB: `publish_state`. Default: `'draft'`.
 */
type PublishState = 'draft' | 'published';
/**
 * Likert scale direction for a metric.
 *
 * DB: `scale`. Mandatory on the platform. Default: `'high'`.
 */
type ScaleDirection = 'low' | 'high';
/**
 * Collection method for a metric. Friendly values; the plugin maps them to the
 * backend (`method`, default `assessment`):
 * - `assessment`→`assessment` — answered during the assessment
 * - `defaultAnswerFromField`→`condfield` — default answer pulled from a source field
 * - `defaultAnswerFromScript`→`condscript` — default answer produced by a script
 * - `script`→`script` — value computed entirely by a script
 */
type MetricMethod = 'assessment' | 'defaultAnswerFromField' | 'defaultAnswerFromScript' | 'script';
/**
 * Controls when a conditional question is asked. Friendly values; the plugin maps
 * them to the backend (`cond_question`, default `always`):
 * - `ifFieldEmpty`→`emptyfield` — only if the default-answer field was empty
 * - `ifScriptEmpty`→`emptyscript` — only if the script provides no default answer
 * - `always`→`always` — always ask the question
 */
type CondQuestion = 'ifFieldEmpty' | 'ifScriptEmpty' | 'always';
/**
 * Rendering style for string-answer metrics. Friendly values; the plugin maps them
 * to the backend (`string_option`, default `short`):
 * - `singleLine`→`short`
 * - `singleLineWide`→`wide`
 * - `multiline`→`multiline`
 */
type StringOption = 'singleLine' | 'singleLineWide' | 'multiline';
/**
 * Dependent plugin value for conditional scripted metrics.
 *
 * DB: `plugin`. Values are the user-facing choice labels.
 */
type DependentPlugin = 'Software Asset Management' | 'Core' | 'CMDB' | 'Procurement' | 'Cost Management' | 'Asset Management';
/**
 * Full configuration for a single answer option / scale point
 * (`asmt_metric_definition`). The option's stored `value` is the key in the
 * {@link BaseMetricConfig.definitions} map, so it is not repeated here.
 */
type MetricDefinitionConfig = {
    /** Display label shown to the assessor. DB: `display`. */
    label: string;
    /** Display order (lower sorts first). DB: `order` (integer). Defaults to the key's position. */
    order?: number;
    /** Score normalization input. DB: `normalization_input` (integer). */
    normalizationInput?: number;
    /** Image shown when this option is selected (for `dataType: 'imageScale'`). DB: `selected_image`. */
    selectedImage?: string;
    /** Image shown when this option is not selected (for `dataType: 'imageScale'`). DB: `unselected_image`. */
    unselectedImage?: string;
};
/**
 * An answer option / scale point: either a display label (shorthand) or a full
 * {@link MetricDefinitionConfig} object.
 */
type MetricDefinitionValue = string | MetricDefinitionConfig;
/**
 * Fields common to every metric, regardless of `dataType`. The data-type-specific
 * fields live on the per-type branches of {@link MetricConfig}.
 */
type BaseMetricConfig = {
    /** Question label shown to the assessor. DB: `name` (string, max 255). Mandatory. */
    name: string;
    /** Rich-text question body. DB: `question` (translated_text, max 512). Mandatory. */
    question: string;
    /** Help/description text. DB: `description` (translated_text, max 1000). */
    description?: string;
    /** Additional rich-text details. DB: `details` (translated_html, max 8000). */
    details?: string;
    /** Whether the metric contributes to the score. DB: `scored`. Default false. */
    scored?: boolean;
    /** Relative weight within its category. DB: `weight` (decimal, max 15). Mandatory. Default 10. */
    weight?: number;
    /** Display order within the category (lower sorts first). DB: `order` (integer). Mandatory. Default 100. */
    order?: number;
    /** Whether an answer is required. DB: `mandatory`. Default false. */
    mandatory?: boolean;
    /** Render the metric as read-only. DB: `read_only`. Default false. */
    readOnly?: boolean;
    /** Whether the metric is active. DB: `active`. Default true. */
    active?: boolean;
    /** Allow the assessor to mark the metric "not applicable". DB: `allow_not_applicable`. Default false. */
    allowNotApplicable?: boolean;
    /** Allow free-text additional information alongside the answer. DB: `allow_add_info`. Default false. */
    allowAdditionalInformation?: boolean;
    /** Label for the additional-information field. DB: `add_info_label` (translated_text, max 255). Default 'Additional Information'. */
    additionalInformationLabel?: string;
    /** Hide the metric label in the rendered survey. DB: `hide_label`. Default false. */
    hideLabel?: boolean;
    /** Dependent plugin value. DB: `plugin`. */
    dependentPlugin?: DependentPlugin;
    /**
     * Conditional question: the sibling metric this one depends on. Reference it with
     * `Now.ref('asmt_metric', '<id-or-sys_id>')`, a `Record<'asmt_metric'>`, or a raw
     * sys_id string; the plugin resolves it to the target metric's sys_id.
     * DB: `depends_on` (reference asmt_metric).
     */
    dependsOn?: string | Record<'asmt_metric'>;
    /** When the dependent question is asked. DB: `cond_question`. Default `'always'`. */
    condQuestion?: CondQuestion;
    /**
     * Dependent answer value(s) that reveal this metric (used with `dependsOn`).
     * DB: `displayed_when` (glide_list -> asmt_metric_definition). Use when the parent
     * (`dependsOn`) metric has `dataType: 'choice'`. Values are the integer keys from
     * the parent metric's `definitions` map.
     */
    displayedWhen?: string | (string | Record<'asmt_metric_definition'>)[];
    /** Reveal value when the parent (`dependsOn`) metric has `dataType: 'yesNo'`. DB: `displayed_when_yesno`. */
    displayedWhenYesNo?: string;
    /** Reveal value when the parent (`dependsOn`) metric has `dataType: 'checkbox'`. DB: `displayed_when_checkbox`. */
    displayedWhenCheckbox?: string;
    /** Reveal value when the parent (`dependsOn`) metric has `dataType: 'template'`. DB: `displayed_when_template` (glide_list -> asmt_template_definition). */
    displayedWhenTemplate?: string | (string | Record<'asmt_template_definition'>)[];
    /** Encoded query controlling when the metric applies. DB: `condition` (conditions, max 1000). */
    condition?: string;
    /** Field the metric reads from (data-collection metrics). DB: `source_field` (field_name). */
    sourceField?: string;
    /** Server script for scripted metrics. DB: `script` (max 4000). Prefer `Now.include('./metric.js')`. */
    script?: string;
    /** Source-record field used to pre-populate the default answer. DB: `default_value_field` (field_name). */
    defaultAnswer?: string;
    /** Collection method for the metric. DB: `method`. Default `'assessment'`. */
    method?: MetricMethod;
    /** Field script validator applied to the answer. DB: `field_validation` (reference sys_cs_field_script_validator). */
    fieldValidation?: string | Record<'sys_cs_field_script_validator'>;
    /** Use the maximum value as the normalization input. DB: `maximum_normalization_input`. Default false. */
    maximumNormalizationInput?: boolean;
    /** Name/value parameters for the metric. DB: `value_parameters` (simple_name_values, max 4000). */
    valueParameters?: string;
    /** Virtual Agent context for chat-based surveys. DB: `context` (reference sys_cs_virtual_agent_context). */
    context?: string | Record<'sys_cs_virtual_agent_context'>;
    /** Maximum weight used when normalizing scores */
    maxWeight?: number;
    /**
     * Answer options / scale points for the metric (`asmt_metric_definition`), keyed by
     * the option's stored `value`. Each entry is a display label (shorthand) or a
     * {@link MetricDefinitionConfig} object. Applicable to choice, likertScale,
     * numericScale, imageScale, multipleSelection and ranking answer types. Coalesced
     * on `value` within this metric (the `metric` FK is wired automatically), so no
     * `$id` is needed.
     *
     * The `asmt_metric_definition.value` column is numeric on the platform, so keys
     * must be integer strings. Non-integer keys produce a build diagnostic.
     *
     * ```ts
     * definitions: {
     *     '1': 'Dissatisfied',
     *     '2': 'Neutral',
     *     '3': { label: 'Satisfied', order: 300 },
     * }
     * ```
     */
    definitions?: {
        [value: string]: MetricDefinitionValue;
    };
};
/**
 * An individual question/metric (`asmt_metric`). A discriminated union keyed on
 * `dataType` — only the fields relevant to the chosen data type are available.
 * The `metric_type` and `category` foreign keys are wired automatically from the
 * nesting structure.
 */
type MetricConfig = Now.Internal.WithID<BaseMetricConfig & ({
    /** Single/multi-line text answer. DB: `datatype` = `string`. */
    dataType: 'string';
    /** Rendering style for string-answer metrics. DB: `string_option`. Default `'singleLine'`. */
    stringOption?: StringOption;
} | {
    /** Lookup answer pointing at another table. DB: `datatype` = `reference`. */
    dataType: 'reference';
    /** Target table for the lookup. DB: `reference_table` (table_name). Required for this type. */
    referenceTable: TableName;
} | {
    /** Likert scale answer. DB: `datatype` = `scale`. */
    dataType: 'likertScale';
    /** Likert scale direction. DB: `scale`. Mandatory. Default `'high'`. */
    scaleDefinition?: ScaleDirection;
} | {
    /** Single-choice answer. DB: `datatype` = `choice`. */
    dataType: 'choice';
    /** Correct answer. DB: `correct_answer_choice` (glide_list -> asmt_metric_definition). */
    correctAnswerChoice?: string | (string | Record<'asmt_metric_definition'>)[];
    /** Randomize the order of answer choices. DB: `randomize_answers`. Default false. */
    randomizeAnswers?: boolean;
} | {
    /** Checkbox answer. DB: `datatype` = `checkbox`. */
    dataType: 'checkbox';
    /** Correct answer. DB: `correct_answer_checkbox`. */
    correctAnswerCheckbox?: string;
} | {
    /** Yes/No answer. DB: `datatype` = `boolean`. */
    dataType: 'yesNo';
    /** Correct answer (Yes/No). DB: `correct_answer_yesno`. */
    correctAnswerYesNo?: string;
} | {
    /** Template-driven answer. DB: `datatype` = `template`. */
    dataType: 'template';
    /** Assessment template backing this metric. DB: `template` (reference asmt_template). */
    template?: string | Record<'asmt_template'>;
    /** Correct answer. DB: `correct_answer_template` (glide_list -> asmt_template_definition). */
    correctAnswerTemplate?: string | (string | Record<'asmt_template_definition'>)[];
} | {
    /** Duration answer. DB: `datatype` = `duration`. */
    dataType: 'duration';
    /** Duration value. DB: `duration` (glide_duration). */
    duration?: string;
} | {
    /** Custom metric-definition answer. DB: `datatype` = `custom`. */
    dataType: 'custom';
    /** Custom metric definition backing this metric. DB: `custom_metric` (reference asmt_custom_metric). */
    customMetric?: string | Record<'asmt_custom_metric'>;
} | {
    /** Numeric answer. DB: `datatype` = `long` (number), `percentage`, or `numericscale`. */
    dataType: 'number' | 'percentage' | 'numericScale';
    /** Minimum numeric value. DB: `min` (integer). Default 0. */
    min?: number;
    /** Maximum numeric value. DB: `max` (integer). Default 10. */
    max?: number;
    /** Expected correct answer for scored numeric questions. DB: `correct_answer` (integer). */
    correctAnswer?: number;
} | {
    /** Answer types that take no data-type-specific fields beyond the base. */
    dataType: 'attachment' | 'date' | 'dateTime' | 'imageScale' | 'ranking' | 'ratings' | 'multipleSelection';
})>;
/**
 * A section within the assessment (`asmt_metric_category`). The `metric_type`
 * foreign key is wired automatically from the parent assessment.
 */
type CategoryConfig = Now.Internal.WithID<{
    /** Category/section name. DB: `name` (translated_text, max 255). Mandatory. */
    name: string;
    /** Rich-text description. DB: `description` (translated_text, max 1000). */
    description?: string;
    /** Additional rich-text details. DB: `details` (translated_html, max 8000). */
    details?: string;
    /** Relative weight of this category in the overall score. DB: `weight` (decimal, max 15). Mandatory. Default 10. */
    weight?: number;
    /** Display order within the assessment (lower sorts first). DB: `order` (integer). Default 1. */
    order?: number;
    /** Scoring strategy for this category. DB: `scoring_type`. Default `'percentage'`. */
    scoringType?: ScoringType;
    /** Roles required to view or take this category. DB: `roles` (user_roles, max 200). */
    roles?: (string | Role)[];
    /** Encoded query that filters which records this category applies to. DB: `filter` (conditions, max 4000). */
    filter?: string;
    /** Auto-create stakeholder records for this category. DB: `create_stakeholders`. Default false. */
    createStakeholders?: boolean;
    /**
     * The questions/metrics in this category, as an array. Each entry is contextually
     * typed by {@link MetricConfig}, so its `dataType` narrows the discriminated union.
     * To make one question depend on another, reference the sibling's id directly:
     *
     * ```ts
     * metrics: [
     *     {
     *         $id: Now.ID['q-has-policy'],
     *         name: 'Has a policy?',
     *         question: 'Do you have a written policy?',
     *         dataType: 'yesNo',
     *     },
     *     {
     *         $id: Now.ID['q-url'],
     *         name: 'Policy URL',
     *         question: 'Link to it',
     *         dataType: 'string',
     *         dependsOn: Now.ID['q-has-policy'],
     *         displayedWhenYesNo: 'Yes',
     *     },
     * ]
     * ```
     */
    metrics?: MetricConfig[];
    /**
     * Evaluation method used when sourcing questions from a question bank.
     * DB: `qb_evaluation_method`. Read-only on the platform.
     */
    questionBankEvaluationMethod?: QbEvaluationMethod;
    /**
     * Table this category's records are drawn from. DB: `table` (table_name).
     * Read-only on the platform.
     */
    table?: TableName;
}>;
/**
 * Fields shared by every `asmt_metric_type` definition, regardless of
 * {@link AssessmentConfig.evaluationMethod}, excluding `table` (and `$id`/metadata).
 * Exported so other plugins built on the same underlying entity — including ones
 * where `table` isn't user-configurable, like `RiskAssessment` (always
 * `change_request`) — can build their own config type on top of it.
 */
export type AssessmentFields<T extends TableName = TableName> = {
    /** Display name of the assessment/survey. DB: `name` (translated_text, max 255). Mandatory. */
    name: string;
    /** Rich-text description of the assessment. DB: `description` (translated_text, max 1000). */
    description?: string;
    /** Introduction HTML shown before the survey begins. DB: `introduction` (translated_html, max 8000). */
    introduction?: string;
    /** Closing note HTML shown after submit. DB: `end_note` (translated_html, max 8000). */
    endNote?: string;
    /** Suppress the introduction note. DB: `not_show_intro_note`. Default false. */
    hideSurveyIntroductionNotes?: boolean;
    /** Whether the assessment is active and can be issued. DB: `active`. Default true. */
    active?: boolean;
    /**
     * Alternate source table used to generate the list of assessable records.
     * When set, candidate records are pulled from this table instead of {@link table},
     * but the assessment itself still targets `table`. Both fields can co-exist.
     * DB: `source_table` (table_name).
     */
    sourceTable?: TableName;
    /** Encoded query selecting which records get assessed. DB: `condition` (conditions, max 1000). */
    condition?: string;
    /** Strategy used to score responses. DB: `scoring_type`. Default `'percentage'`. */
    scoringType?: ScoringType;
    /**
     * Score scale factor — an integer that determines the score range.
     * Typical values are `1` (raw), `10` (tens), or `100` (percentage).
     * DB: `scale_factor` (integer). Required when `evaluationMethod` is
     * `'assessment'` (the default); optional when `'survey'`.
     */
    scaleFactor?: number;
    /** Trigger model for generating assessment instances. DB: `schedule_type`. Default `'onDemand'`. */
    scheduleType?: ScheduleType;
    /** Recurrence period, used with `scheduleType: 'scheduled'`. DB: `schedule_period`. Default `'noLimit'`. */
    schedulePeriod?: SchedulePeriod;
    /** How long an assessment instance stays open. DB: `duration` (glide_duration). Default `Duration({ days: 14 })` (`'1970-01-15 00:00:00'`). */
    assessmentDuration?: Duration;
    /** Allow assessors to retake the assessment. DB: `allow_retake`. Default false. */
    allowRetake?: boolean;
    /** Anonymize responses. DB: `anonymize`. Default false. */
    anonymizeResponses?: boolean;
    /** Roles required to take the assessment. DB: `roles` (user_roles, max 200). */
    roles?: (string | Role)[];
    /**
     * Column name on {@link table} (or {@link sourceTable}) that identifies the user
     * being assessed. Conceptually `keyof table`. DB: `user_field` (field_name).
     */
    userField?: keyof FullSchema<T> | (string & {});
    /**
     * Field on {@link table} that identifies the filter-menu choices on decision matrices
     * and scorecards; selecting a value scopes the comparison pool (e.g. `'assignment_group'`
     * on `incident` compares within a group — it segments, not ranks). Conceptually
     * `keyof table`. DB: `display_field` (field_name).
     */
    filterField?: keyof FullSchema<T> | (string & {});
    /** Public URL for anonymous or one-click surveys. DB: `url` (max 500). */
    returnUrl?: string;
    /** Publish events to the live feed. DB: `live_feed`. Default false. */
    liveFeed?: boolean;
    /** Expose the survey through chat / Virtual Agent. DB: `chat_survey`. Default false. */
    chatSurvey?: boolean;
    /** Enable one-click survey links. DB: `one_click_survey`. Default false. */
    oneClickSurvey?: boolean;
    /** Service Portal pagination mode. DB: `portal_pagination`. Default `'category'`. */
    portalPagination?: PortalPagination;
    /** Survey owners. DB: `survey_owners` (glide_list -> sys_user, max 1024). */
    owners?: (string | Record<'sys_user'>)[];
    /** Notify the assessed user when an instance is created. DB: `notify_user`. Default true. */
    sendNotifications?: boolean;
    /** Notify when an assessment instance is overdue. DB: `notify_if_overdue`. Default false. */
    notifyIfOverdue?: boolean;
    /** User to notify on overdue instances. DB: `overdue_notify_user` (reference sys_user). */
    assessmentManager?: string | Record<'sys_user'>;
    /** Signature definition to require on completion. DB: `signature` (reference asmt_signature). */
    signature?: string | Record<'asmt_signature'>;
    /** Enforce the condition strictly. DB: `enforce_condition`. Default false. */
    enforceCondition?: boolean;
    /** Show all filters on the assessment. DB: `display_all_filters`. Default false. */
    displayAllFilters?: boolean;
    /** Filter condition (encoded query). DB: `filter_condition` (conditions, max 1000). */
    filterCondition?: string;
    /** Default filter (encoded query). DB: `default_filter`. */
    defaultMatrixFilter?: string;
    /** Publish lifecycle state. DB: `publish_state`. Default `'draft'`. */
    state?: PublishState;
    /** Sample metric used for previews. DB: `sample_metric` (reference asmt_metric). */
    sampleMetric?: string | Record<'asmt_metric'>;
    /** The categories (sections) of the assessment. */
    categories?: CategoryConfig[];
    /**
     * Allow the assessment to be taken by public (unauthenticated) users.
     * DB: `allow_public`. Read-only on the platform — populate only if your
     * build plugin sets it explicitly. Default false.
     */
    allowPublic?: boolean;
    /** Auto-generated business rule that triggers when the metric type is created. Do not set manually. */
    businessRule?: string;
    /** Auto-generated business rule that triggers when the metric type is deleted. Do not set manually. */
    deleteBusinessRule?: string;
    /**
     * Auto-generated recurring job that regenerates assessment instances when
     * `scheduleType` is `'scheduled'`. DB: `job` (reference sys_trigger). Do not set manually.
     */
    scheduleJob?: string;
    /**
     * Auto-generated business rule that updates assessable record category ownership
     * when the assessment is updated. DB: `user_field_business_rule` (reference sys_script).
     * Do not set manually.
     */
    userFieldBusinessRule?: string;
};
/**
 * Fields shared by every `asmt_metric_type` definition, regardless of
 * {@link AssessmentConfig.evaluationMethod}.
 */
type BaseAssessmentConfig<T extends TableName = TableName> = Now.Internal.WithIdAndMetadata<AssessmentFields<T> & {
    /**
     * The table this assessment is about (the source records being assessed).
     * DB: `table` (table_name). Required when `evaluationMethod` is `'assessment'`
     * (the default); optional when `'survey'`.
     */
    table?: T;
}>;
/**
 * An assessment/survey definition (`asmt_metric_type`), together with its
 * categories and metrics, expressed as a single nested entity.
 */
export type AssessmentConfig<T extends TableName = TableName> = BaseAssessmentConfig<T> & {
    /**
     * Determines whether this definition behaves as a scored assessment evaluated
     * against `table` records, or as an unscored survey with no target table.
     * DB: `evaluation_method`. Mandatory; defaults to `'assessment'` when omitted.
     * When `'assessment'`, `table` and `scaleFactor` are required.
     */
    evaluationMethod?: 'assessment' | 'survey';
};
/**
 * Creates a ServiceNow assessment/survey definition (`asmt_metric_type`) together
 * with its categories (`asmt_metric_category`) and questions/metrics (`asmt_metric`)
 * as a single nested entity. The `metric_type` and `category` foreign keys are wired
 * automatically from the nesting structure.
 *
 * @param config - The assessment configuration object
 * @see https://docs.servicenow.com/csh?topicname=assessments-landing-page.html&version=latest
 *
 * @example
 * ```ts
 * Assessment({
 *     $id: Now.ID['nps-survey'],
 *     name: 'Customer NPS',
 *     table: 'customer_account',
 *     categories: [
 *         {
 *             $id: Now.ID['nps-cat'],
 *             name: 'Net Promoter Score',
 *             metrics: [
 *                 {
 *                     $id: Now.ID['nps-q'],
 *                     name: 'How likely are you to recommend us?',
 *                     question: 'How likely are you to recommend us?',
 *                     dataType: 'numericScale',
 *                     scored: false,
 *                 },
 *             ],
 *         },
 *     ],
 * })
 * ```
 */
export declare function Assessment<T extends TableName>(config: AssessmentConfig<T>): AssessmentConfig<T>;
export {};
